function adjustBrightness(hex: string, percent: number): string {
  try {
    const cleanHex = hex.replace("#", "");
    const num = parseInt(cleanHex.length === 3 ? cleanHex.split("").map((c) => c + c).join("") : cleanHex, 16);
    const amt = Math.round(2.55 * percent);
    const R = Math.min(255, Math.max(0, (num >> 16) + amt));
    const G = Math.min(255, Math.max(0, ((num >> 8) & 0x00ff) + amt));
    const B = Math.min(255, Math.max(0, (num & 0x0000ff) + amt));
    return `#${((1 << 24) + (R << 16) + (G << 8) + B).toString(16).slice(1)}`;
  } catch {
    return hex;
  }
}

const COLOR_ALIASES: Record<string, keyof typeof COLOR_MAP> = {
  black: "obsidian",
  dark: "obsidian",
  noir: "obsidian",
  gray: "titanium",
  grey: "titanium",
  silver: "silver",
  white: "glacier",
  blanc: "glacier",
  red: "crimson",
  rouge: "crimson",
  blue: "sapphire",
  bleu: "sapphire",
  green: "emerald",
  vert: "emerald",
  orange: "amber",
  yellow: "champagne",
  gold: "champagne",
  pearl: "pearl",
  carbon: "carbon",
};

export function resolveCarColors(colorNameOrHex?: CarColorVariant): ResolvedCarColors {
  if (!colorNameOrHex) return COLOR_MAP.obsidian;
  const normalized = colorNameOrHex.trim().toLowerCase();
  if (COLOR_MAP[normalized as keyof typeof COLOR_MAP]) {
    return COLOR_MAP[normalized as keyof typeof COLOR_MAP];
  }
  if (COLOR_ALIASES[normalized]) {
    return COLOR_MAP[COLOR_ALIASES[normalized]];
  }

  if (colorNameOrHex.startsWith("#")) {
    return {
      body: colorNameOrHex,
      bodyHighlight: adjustBrightness(colorNameOrHex, 22),
      bodyShadow: adjustBrightness(colorNameOrHex, -26),
      glass: "#18181B",
      glassGlare: "rgba(255, 255, 255, 0.22)",
      roof: adjustBrightness(colorNameOrHex, -15),
      rim: "#D4D4D8",
      caliper: "#EF4444",
    };
  }

  return COLOR_MAP.obsidian;
}

