/**
 * UltraRealisticCar
 * 
 * High-fidelity top-down automotive vector model.
 * Renders authentic vector geometries based on user SVG assets (Sedan, Hatchback, Horizontal),
 * supporting full dynamic palette and hex coloring, scaling, and orientation.
 */
export const UltraRealisticCar: React.FC<CarProps> = ({
  color = "obsidian",
  orientation = "horizontal",
  model = "sedan",
  scale = 1,
  width,
  height,
}) => {
  const resolvedColors = resolveCarColors(color);

  if (orientation === "horizontal") {
    return (
      <View style={styles.centerBox}>
        <HorizontalCarSvg
          color={resolvedColors}
          scale={scale}
          width={width}
          height={height}
        />
      </View>
    );
  }

  // Vertical orientation
  if (model === "hatchback") {
    return (
      <View style={styles.centerBox}>
        <VerticalHatchbackSvg
          color={resolvedColors}
          scale={scale}
          width={width}
          height={height}
        />
      </View>
    );
  }

  // Default vertical is executive sedan
  return (
    <View style={styles.centerBox}>
      <VerticalSedanSvg
        color={resolvedColors}
        scale={scale}
        width={width}
        height={height}
      />
    </View>
  );
};

export const HorizontalUltraRealisticCar: React.FC<Omit<CarProps, "orientation">> = (props) => (
  <UltraRealisticCar orientation="horizontal" {...props} />
);

export const VerticalUltraRealisticCar: React.FC<Omit<CarProps, "orientation">> = (props) => (
  <UltraRealisticCar orientation="vertical" {...props} />
);

export const SedanCar: React.FC<Omit<CarProps, "orientation" | "model">> = (props) => (
  <UltraRealisticCar orientation="vertical" model="sedan" {...props} />
);

export const HatchbackCar: React.FC<Omit<CarProps, "orientation" | "model">> = (props) => (
  <UltraRealisticCar orientation="vertical" model="hatchback" {...props} />
);

const styles = StyleSheet.create({
  centerBox: {
    alignItems: "center",
    justifyContent: "center",
  },
});
